  1	package com.pousada.marealta;
  2	
  3	import io.javalin.Javalin;
  4	import io.javalin.http.HttpStatus;
  5	import com.google.gson.Gson;
  6	import com.google.gson.GsonBuilder;
  7	import com.pousada.marealta.api.ApiError;
  8	import com.pousada.marealta.api.request.CreateReservationRequest;
  9	import com.pousada.marealta.api.response.ReservationResponse;
 10	import com.pousada.marealta.api.response.DocumentResponse;
 11	import com.pousada.marealta.api.response.MessageResponse;
 12	import com.pousada.marealta.db.Database;
 13	import com.pousada.marealta.db.RoomRepository;
 14	import com.pousada.marealta.db.ReservationRepository;
 15	import com.pousada.marealta.db.MessageRepository;
 16	import com.pousada.marealta.enums.RatePlan;
 17	import com.pousada.marealta.model.Reservation;
 18	import com.pousada.marealta.model.Document;
 19	import com.pousada.marealta.model.Room;
 20	import com.pousada.marealta.notification.NotificationManager;
 21	import com.pousada.marealta.notification.notifiers.GuestNotifier;
 22	import com.pousada.marealta.notification.notifiers.HousekeepingNotifier;
 23	import com.pousada.marealta.notification.notifiers.FinanceNotifier;
 24	import com.pousada.marealta.service.ReservationService;
 25	import com.pousada.marealta.service.ReportService;
 26	import com.pousada.marealta.util.DocumentGenerator;
 27	import java.math.BigDecimal;
 28	import java.time.LocalDate;
 29	import java.time.YearMonth;
 30	import java.time.format.DateTimeFormatter;
 31	
 32	public class App {
 33	    private static final Gson gson = new GsonBuilder().setPrettyPrinting().create();
 34	
 35	    public static void main(String[] args) throws Exception {
 36	        String dbUrl = System.getenv("DB_URL");
 37	        String dbUser = System.getenv("DB_USER");
 38	        String dbPassword = System.getenv("DB_PASSWORD");
 39	        String portStr = System.getenv("PORT");
 40	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 41	
 42	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 43	            throw new IllegalArgumentException("DB_URL, DB_USER, and DB_PASSWORD environment variables are required");
 44	        }
 45	
 46	        Database.initialize(dbUrl, dbUser, dbPassword);
 47	        initializeNotifiers();
 48	
 49	        Javalin app = Javalin.create();
 50	
 51	        app.get("/rooms", ctx -> {
 52	            try {
 53	                var rooms = RoomRepository.findAll();
 54	                ctx.json(rooms.stream().map(r -> new Object() {
 55	                    public int number = r.getNumber();
 56	                    public String type = r.getType().displayName;
 57	                    public int capacity = r.getCapacity();
 58	                    public String nightlyRate = String.format("%.2f", r.getNightlyRate());
 59	                }).toList());
 60	            } catch (Exception e) {
 61	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
 62	            }
 63	        });
 64	
 65	        app.post("/reservations", ctx -> {
 66	            try {
 67	                CreateReservationRequest req = gson.fromJson(ctx.body(), CreateReservationRequest.class);
 68	
 69	                if (req.roomNumber <= 0 || req.guestName == null || req.guestEmail == null ||
 70	                    req.guestCpf == null || req.checkIn == null || req.checkOut == null ||
 71	                    req.guests <= 0 || req.ratePlan == null) {
 72	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "Missing required fields"));
 73	                    return;
 74	                }
 75	
 76	                LocalDate checkIn = LocalDate.parse(req.checkIn);
 77	                LocalDate checkOut = LocalDate.parse(req.checkOut);
 78	                RatePlan ratePlan = RatePlan.valueOf(req.ratePlan);
 79	
 80	                Reservation reservation = ReservationService.createReservation(
 81	                    req.roomNumber, req.guestName, req.guestEmail, req.guestCpf,
 82	                    checkIn, checkOut, req.guests, ratePlan
 83	                );
 84	
 85	                ctx.status(201).json(new ReservationResponse(reservation));
 86	            } catch (IllegalArgumentException e) {
 87	                handleError(ctx, e.getMessage());
 88	            } catch (Exception e) {
 89	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
 90	            }
 91	        });
 92	
 93	        app.get("/reservations/{id}", ctx -> {
 94	            try {
 95	                long id = Long.parseLong(ctx.pathParam("id"));
 96	                Reservation reservation = ReservationRepository.findById(id);
 97	
 98	                if (reservation == null) {
 99	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
100	                    return;
101	                }
102	
103	                ctx.json(new ReservationResponse(reservation));
104	            } catch (Exception e) {
105	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
106	            }
107	        });
108	
109	        app.post("/reservations/{id}/confirmation", ctx -> {
110	            try {
111	                long id = Long.parseLong(ctx.pathParam("id"));
112	                Reservation reservation = ReservationRepository.findById(id);
113	
114	                if (reservation == null) {
115	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
116	                    return;
117	                }
118	
119	                Reservation confirmed = ReservationService.confirmReservation(id, reservation.getTotal());
120	                ctx.json(new ReservationResponse(confirmed));
121	            } catch (IllegalArgumentException e) {
122	                handleError(ctx, e.getMessage());
123	            } catch (Exception e) {
124	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
125	            }
126	        });
127	
128	        app.post("/reservations/{id}/cancellation", ctx -> {
129	            try {
130	                long id = Long.parseLong(ctx.pathParam("id"));
131	                Reservation cancelled = ReservationService.cancelReservation(id);
132	                ctx.json(new ReservationResponse(cancelled));
133	            } catch (IllegalArgumentException e) {
134	                handleError(ctx, e.getMessage());
135	            } catch (Exception e) {
136	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
137	            }
138	        });
139	
140	        app.post("/reservations/{id}/check-in", ctx -> {
141	            try {
142	                long id = Long.parseLong(ctx.pathParam("id"));
143	                Reservation checkedIn = ReservationService.checkIn(id);
144	                ctx.json(new ReservationResponse(checkedIn));
145	            } catch (IllegalArgumentException e) {
146	                handleError(ctx, e.getMessage());
147	            } catch (Exception e) {
148	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
149	            }
150	        });
151	
152	        app.post("/reservations/{id}/check-out", ctx -> {
153	            try {
154	                long id = Long.parseLong(ctx.pathParam("id"));
155	                Reservation reservation = ReservationRepository.findById(id);
156	
157	                if (reservation == null) {
158	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
159	                    return;
160	                }
161	
162	                ReservationService.checkOut(id);
163	                Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
164	                Document doc = new Document(
165	                    reservation.getId(),
166	                    reservation.getGuestName(),
167	                    reservation.getGuestCpf(),
168	                    reservation.getRoomNumber(),
169	                    room.getType().displayName,
170	                    reservation.getCheckIn(),
171	                    reservation.getCheckOut(),
172	                    reservation.getNights(),
173	                    reservation.getSubtotal(),
174	                    reservation.getDiscount(),
175	                    reservation.getTotal()
176	                );
177	
178	                ctx.json(new DocumentResponse(doc));
179	            } catch (IllegalArgumentException e) {
180	                handleError(ctx, e.getMessage());
181	            } catch (Exception e) {
182	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
183	            }
184	        });
185	
186	        app.get("/reservations/{id}/document", ctx -> {
187	            try {
188	                long id = Long.parseLong(ctx.pathParam("id"));
189	                Reservation reservation = ReservationRepository.findById(id);
190	
191	                if (reservation == null) {
192	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
193	                    return;
194	                }
195	
196	                if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
197	                    ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Document not available"));
198	                    return;
199	                }
200	
201	                Room room = RoomRepository.findByNumber(reservation.getRoomNumber());
202	                Document doc = new Document(
203	                    reservation.getId(),
204	                    reservation.getGuestName(),
205	                    reservation.getGuestCpf(),
206	                    reservation.getRoomNumber(),
207	                    room.getType().displayName,
208	                    reservation.getCheckIn(),
209	                    reservation.getCheckOut(),
210	                    reservation.getNights(),
211	                    reservation.getSubtotal(),
212	                    reservation.getDiscount(),
213	                    reservation.getTotal()
214	                );
215	
216	                ctx.json(new DocumentResponse(doc));
217	            } catch (Exception e) {
218	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
219	            }
220	        });
221	
222	        app.get("/messages", ctx -> {
223	            try {
224	                var messages = MessageRepository.findAll();
225	                ctx.json(messages.stream().map(MessageResponse::new).toList());
226	            } catch (Exception e) {
227	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
228	            }
229	        });
230	
231	        app.get("/reports/occupancy", ctx -> {
232	            try {
233	                String dateStr = ctx.queryParam("date");
234	                if (dateStr == null) {
235	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "date parameter is required"));
236	                    return;
237	                }
238	
239	                LocalDate date = LocalDate.parse(dateStr);
240	                String csv = ReportService.generateOccupancyReport(date);
241	                ctx.contentType("text/csv; charset=utf-8").result(csv);
242	            } catch (Exception e) {
243	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
244	            }
245	        });
246	
247	        app.get("/reports/revenue", ctx -> {
248	            try {
249	                String monthStr = ctx.queryParam("month");
250	                if (monthStr == null) {
251	                    ctx.status(400).json(new ApiError("INVALID_REQUEST", "month parameter is required"));
252	                    return;
253	                }
254	
255	                YearMonth yearMonth = YearMonth.parse(monthStr);
256	                String csv = ReportService.generateRevenueReport(yearMonth);
257	                ctx.contentType("text/csv; charset=utf-8").result(csv);
258	            } catch (Exception e) {
259	                ctx.status(400).json(new ApiError("INVALID_REQUEST", e.getMessage()));
260	            }
261	        });
262	
263	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
264	            Database.close();
265	        }));
266	
267	        app.start(port);
268	    }
269	
270	    private static void initializeNotifiers() {
271	        NotificationManager.registerNotifier(new GuestNotifier());
272	        NotificationManager.registerNotifier(new HousekeepingNotifier());
273	        NotificationManager.registerNotifier(new FinanceNotifier());
274	    }
275	
276	    private static void handleError(io.javalin.http.Context ctx, String error) {
277	        switch (error) {
278	            case "ROOM_NOT_FOUND":
279	                ctx.status(404).json(new ApiError("ROOM_NOT_FOUND", "Room not found"));
280	                break;
281	            case "RESERVATION_NOT_FOUND":
282	                ctx.status(404).json(new ApiError("RESERVATION_NOT_FOUND", "Reservation not found"));
283	                break;
284	            case "ROOM_UNAVAILABLE":
285	                ctx.status(409).json(new ApiError("ROOM_UNAVAILABLE", "Room is not available for the requested dates"));
286	                break;
287	            case "OPERATION_NOT_ALLOWED":
288	                ctx.status(409).json(new ApiError("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
289	                break;
290	            case "CAPACITY_EXCEEDED":
291	                ctx.status(422).json(new ApiError("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
292	                break;
293	            case "INVALID_REQUEST":
294	                ctx.status(400).json(new ApiError("INVALID_REQUEST", "Invalid request"));
295	                break;
296	            default:
297	                ctx.status(400).json(new ApiError("INVALID_REQUEST", error));
298	        }
299	    }
300	}

