    15	public class ReservationService {
    16	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    17	                                               String guestCpf, LocalDate checkIn, LocalDate checkOut,
    18	                                               int guests, RatePlan ratePlan) throws Exception {
    19	        validateReservationInput(roomNumber, checkIn, checkOut, guests, ratePlan);
    20	
    21	        Room room = RoomRepository.findByNumber(roomNumber);
    22	        if (room == null) {
    23	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    24	        }
    25	
    26	        if (guests > room.getCapacity()) {
    27	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    28	        }
    29	
    30	        if (guests < 1) {
    31	            throw new IllegalArgumentException("INVALID_REQUEST");
    32	        }
    33	
    34	        var conflictingReservations = ReservationRepository.findByRoomAndDates(
    35	            roomNumber, checkIn, checkOut,
    36	            ReservationStatus.CONFIRMED, ReservationStatus.CHECKED_IN, ReservationStatus.CHECKED_OUT
    37	        );
    38	
    39	        if (!conflictingReservations.isEmpty()) {
    40	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    41	        }
    42	
    43	        int nights = PricingCalculator.countNights(checkIn, checkOut);
    44	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    45	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
    46	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
    47	
    48	        return ReservationRepository.create(
    49	            roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan,
    50	            nights, subtotal, discount, total
    51	        );
    52	    }
    53	
    54	    public static Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws Exception {
    55	        Reservation reservation = ReservationRepository.findById(reservationId);
    56	        if (reservation == null) {
    57	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    58	        }
    59	
    60	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    61	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    62	        }
    63	
    64	        ReservationRepository.updateStatusAndAmountPaid(reservationId, ReservationStatus.CONFIRMED, amountPaid);
    65	        Reservation confirmed = ReservationRepository.findById(reservationId);
    66	
    67	        NotificationManager.notify(new ReservationEvent(ReservationEvent.Type.CONFIRMED, confirmed));
    68	
    69	        return confirmed;
    70	    }
    71	
    72	    public static Reservation checkIn(long reservationId) throws Exception {
    73	        Reservation reservation = ReservationRepository.findById(reservationId);
    74	        if (reservation == null) {
    75	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
    76	        }
    77	
    78	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    79	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
    80	        }
    81	
    82	        ReservationRepository.updateStatus(reservationId, ReservationStatus.CHECKED_IN);
    83	        return ReservationRepository.findById(reservationId);
