    99	
   100	    public static Reservation cancelReservation(long reservationId) throws Exception {
   101	        Reservation reservation = ReservationRepository.findById(reservationId);
   102	        if (reservation == null) {
   103	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   104	        }
   105	
   106	        ReservationStatus status = reservation.getStatus();
   107	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
   108	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   109	        }
   110	
   111	        BigDecimal refund = BigDecimal.ZERO;
   112	
   113	        if (status == ReservationStatus.CONFIRMED) {
   114	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
   115	                refund = reservation.getAmountPaid();
   116	            }
   117	        }
   118	
   119	        ReservationRepository.updateRefund(reservationId, refund);
   120	        ReservationRepository.updateStatus(reservationId, ReservationStatus.CANCELLED);
   121	
   122	        Reservation cancelled = ReservationRepository.findById(reservationId);
   123	
   124	        if (status == ReservationStatus.CONFIRMED) {
   125	            NotificationManager.notify(new ReservationEvent(ReservationEvent.Type.CANCELLED, cancelled));
   126	        }
   127	
   128	        return cancelled;
   129	    }
   130	
   131	    private static void validateReservationInput(int roomNumber, LocalDate checkIn, LocalDate checkOut,
   132	                                                int guests, RatePlan ratePlan) throws Exception {
   133	        if (roomNumber <= 0 || checkIn == null || checkOut == null || ratePlan == null) {
   134	            throw new IllegalArgumentException("INVALID_REQUEST");
   135	        }
   136	
   137	        if (!checkOut.isAfter(checkIn)) {
   138	            throw new IllegalArgumentException("INVALID_REQUEST");
   139	        }
   140	
   141	        if (guests < 1) {
   142	            throw new IllegalArgumentException("INVALID_REQUEST");
   143	        }
   144	    }
