    33	    public static String formatCPF(String cpf) {
    34	        if (cpf == null || cpf.length() != 11) return cpf;
    35	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    36	               cpf.substring(6, 9) + "-" + cpf.substring(9);
