     1	package com.pousada.marealta.util;
     2	
     3	import com.pousada.marealta.enums.RatePlan;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	
     8	public class PricingCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	
    12	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
    13	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    14	    }
    15	
    16	    public static boolean isHighSeason(LocalDate date) {
    17	        int month = date.getMonthValue();
    18	        int day = date.getDayOfMonth();
    19	
    20	        if (month == 7) return true;
    21	        if (month == 12) return true;
    22	        if (month >= 1 && month <= 2) return true;
    23	
    24	        return false;
    25	    }
    26	
    27	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    28	        if (isHighSeason(date)) {
    29	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    30	                          .setScale(2, RoundingMode.HALF_EVEN);
    31	        }
    32	        return baseRate;
    33	    }
    34	
    35	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    36	        BigDecimal subtotal = BigDecimal.ZERO;
    37	        LocalDate current = checkIn;
    38	
    39	        while (current.isBefore(checkOut)) {
    40	            BigDecimal nightlyRate = calculateNightlyRate(baseRate, current);
    41	            subtotal = subtotal.add(nightlyRate);
    42	            current = current.plusDays(1);
    43	        }
    44	
    45	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    46	    }
    47	
    48	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    49	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    50	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE)
    51	                          .setScale(2, RoundingMode.HALF_EVEN);
    52	        }
    53	        return BigDecimal.ZERO;
    54	    }
    55	
    56	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    57	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    58	    }
    59	}
